body:
@font-face {
  font-family: "Haffer";
  src: url("./Haffer-Regular.otf") format("opentype");
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "Haffer";
  src: url("./Haffer-Medium.otf") format("opentype");
  font-weight: 500;
  font-display: swap;
}
@font-face {
  font-family: "Haffer";
  src: url("./Haffer-SemiBold.otf") format("opentype");
  font-weight: 600;
  font-display: swap;
}
*,
*::after,
*::before {
  margin: 0;
  padding: 0;
  box-sizing: inherit;
}

html {
  font-size: 62.5%;
  font-family: "Haffer", sans-serif;
  overflow-x: hidden;
  overflow-y: auto;
}

body {
  box-sizing: border-box;
  color: #0f0f23;
  background-color: #faf5f0;
}

a {
  text-decoration: none;
  color: #faf5f0;
}

img {
  width: 100%;
  height: auto;
}

input {
  outline: none;
}

.d-flex {
  display: flex;
}

.d-inline-block {
  display: inline-block;
}

.justify-center {
  justify-content: center;
}

.justify-between {
  justify-content: space-between;
}

.align-center {
  align-items: center;
}

.flex-column {
  flex-direction: column;
}

.d-none {
  display: none;
}

.bold {
  font-weight: 700;
}

.link {
  color: #0f0f23;
  text-decoration: underline;
  transition: all 0.3s;
}
.link:hover {
  color: blue;
}

.align-start {
  align-items: flex-start;
}

@media screen and (max-width: 1024px) {
  .flex-sm-column {
    flex-direction: column;
  }
  .align-sm-start {
    align-items: start;
  }
  .d-sm-none {
    display: none;
  }
  .d-sm-block {
    display: block;
  }
}
.privacy {
  padding: 10rem 2rem;
}
.privacy .core {
  max-width: 40%;
  gap: 4rem;
}
.privacy .core .privacy_title {
  text-align: center;
  font-size: 3rem;
}
.privacy .core .privacy_paragraph .paragraph_title {
  font-size: 2.2rem;
  margin-bottom: 1rem;
}
.privacy .core .privacy_paragraph .paragraph_content {
  font-size: 1.5rem;
  line-height: 1.3;
}
.privacy .core .privacy_paragraph .paragraph_content .subsection {
  display: block;
  font-weight: 700;
  margin-top: 1rem;
}
.privacy .core .privacy_paragraph .paragraph_content ul {
  margin: 1rem 0;
}
.privacy .core .privacy_paragraph .paragraph_content table {
  width: 100%;
  border-collapse: collapse;
}
.privacy .core .privacy_paragraph .paragraph_content th,
.privacy .core .privacy_paragraph .paragraph_content td {
  border: 1px solid black;
  padding: 8px;
  text-align: left;
}
.privacy .core .privacy_paragraph .paragraph_content th {
  background-color: rgba(255, 60, 0, 0.1);
}

@media screen and (max-width: 1024px) {
  .privacy {
    padding: 5rem 3rem;
    width: 100%;
  }
  .privacy .core {
    max-width: 100%;
  }
  .privacy .core .privacy_title {
    font-size: 2rem;
  }
  .privacy .core .privacy_paragraph .paragraph_title {
    font-size: 1.8rem;
    margin-bottom: 2rem;
  }
  .privacy .core .privacy_paragraph .paragraph_content {
    font-size: 1.2rem;
  }
  .privacy .core .privacy_paragraph .paragraph_content table {
    margin-top: 1rem;
  }
  .privacy .core .privacy_paragraph .paragraph_content th,
  .privacy .core .privacy_paragraph .paragraph_content td {
    width: 25%;
  }
}
.landing .hero {
  padding: 4rem 2rem 22rem;
  background-color: #ff3c00;
  clip-path: polygon(0% 0%, 0% 94%, 34% 85%, 30% 100%, 100% 85%, 100% 0%);
  min-height: 70vh;
}
.landing .hero .core header {
  margin-bottom: 6.08rem;
}
.landing .hero .core header .logo {
  width: 60rem;
}
.landing .hero .core header .language-switcher {
  position: absolute;
  top: 4rem;
  right: 4rem;
  gap: 3rem;
  font-size: 1.2rem;
  background: rgba(250, 245, 240, 0.15);
  border: 1px solid var(--Off-white, #faf5f0);
  border-radius: 8px;
  padding: 1.2rem;
}
.landing .hero .core header .language-switcher .language {
  gap: 0.4rem;
  cursor: pointer;
  color: white;
}
.landing .hero .core main .form-section {
  text-align: center;
  gap: 3rem;
}
.landing .hero .core main .form-section .form-text {
