}
.landing .hero .core main .form-section .form-text .subtitle {
  font-size: 2.1rem;
  color: white;
  margin-top: 2rem;
  font-weight: 500;
  line-height: 1.3;
}
.landing .hero .core main .form-section .form-text .subtitle.small {
  font-size: 1.6rem;
}
.landing .hero .core main .form-section .form-text .subtitle .bold {
  display: inline-block;
}
.landing .hero .core main .form-section .form {
  gap: 1.6rem;
  width: 56rem;
}
.landing .hero .core main .form-section .form .input {
  display: block;
  background-color: rgba(250, 245, 240, 0.15);
  border: 1px solid #faf5f0;
  padding: 0 1rem;
  height: 5rem;
  border-radius: 8px;
  font-size: 1.6rem;
  transition: all 0.3s;
  color: #faf5f0;
}
.landing .hero .core main .form-section .form .input::placeholder {
  color: #faf5f0;
}
.landing .hero .core main .form-section .form .input:focus-within, .landing .hero .core main .form-section .form .input:focus-visible {
