}
.landing .hero .core main .form-section .form .details select option {
  color: black;
}
.landing .hero .core main .form-section .form .checkbox {
  color: #faf5f0;
  gap: 0.8rem;
  font-size: 1.3rem;
  text-align: start;
}
.landing .hero .core main .form-section .form .checkbox span {
  text-decoration: underline;
  display: inline-block;
}
.landing .hero .core main .form-section .form .button {
  margin-top: 1.4rem;
  height: 5rem;
  font-size: 1.6rem;
  background-color: #0f0f23;
