  border-radius: 8px;
  color: #faf5f0;
  transition: all 0.3s;
  cursor: pointer;
}
.landing .hero .core main .form-section .form .button:hover {
  background-color: #1e1e47;
}
.landing .hero .core main .form-section .form-disclaimer {
  color: #faf5f0;
  font-size: 1.3rem;
  width: 56rem;
}
.landing .footer {
  padding: 4.4rem 0 10rem;
  gap: 4rem;
}
.landing .footer .paragraph {
  width: 82.7rem;
  text-align: center;
}
.landing .footer .paragraph .p-title {
  margin-bottom: 2.8rem;
  font-size: 4.4rem;
  background: linear-gradient(0deg, #ff3c00 0%, #ff0078 100%);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  color: #ff3c00;
  font-family: "Glober", sans-serif;
}
.landing .footer .paragraph .p-content {
  gap: 2.8rem;
  font-size: 1.8rem;
}
.landing .footer .paragraph .p-content .view {
  padding: 1rem 2rem;
  background: linear-gradient(0deg, #ff3c00 0%, #ff0078 100%);
  width: 13rem;
  font-size: 1.6rem;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s;
}
.landing .footer .paragraph .p-content .view:hover {
  background: linear-gradient(0deg, #ff0078 40%, #ff3c00 100%);
}
.landing .footer .paragraph.sponsorships {
  width: 100%;
}
.landing .footer .paragraph.sponsorships .p-content {
  overflow: hidden;
}
.landing .footer .paragraph.sponsorships .p-content img {
  width: 46.1rem;
}
.landing .footer .paragraph.sponsorships .p-content .logos {
  gap: 1.3rem;
  font-size: 0.8rem;
  font-weight: 700;
  overflow-y: hidden;
  overflow-x: auto;
  text-transform: uppercase;
  padding: 1.5rem 2.5rem;
  width: 90%;
  overflow-y: hidden;
  overflow-x: auto;
  justify-content: space-between;
}
.landing .footer .paragraph.sponsorships .p-content .logos .team_logo,
.landing .footer .paragraph.sponsorships .p-content .logos img {
  width: 5.9rem;
  margin-bottom: 1rem;
}
.landing .footer .paragraph.sponsorships .p-content .logos .title {
  color: #0f0f23;
}
.landing .footer .paragraph.awards .p-content .awards-list {
  flex-wrap: wrap;
  width: 45.6rem;
  row-gap: 0.83rem;
  justify-content: space-between;
}
.landing .footer .paragraph.awards .p-content .awards-list img {
  width: 22.4rem;
}
.landing .footer .paragraph.awards .p-content .awards-disclaimer {
  font-size: 1.4rem;
}
.landing .footer .paragraph.disclaimer .p-content img {
  width: 30rem;
}

